"""Compiles every generated result into results/RESULTS.md (one file to read
and to copy into the report)."""
from __future__ import annotations

from pathlib import Path


def _read(path: Path) -> str:
    return path.read_text(encoding="utf-8").strip() if path.exists() else "(not generated - run this session)"


def main(ctx):
    r = ctx.results
    parts = [
        "# Results - Soft Computing mini-project (auto-generated by run_experiments.py)\n",
        "Do not edit by hand: rerun `python run_experiments.py`.\n",
        "## Machine and timing method\n", "```", _read(r / "env_info.txt"), "```",
        "## Session 1 - classic reference\n", "```", _read(r / "s1_ablation.txt"), "",
        _read(r / "s1_dt_comparison.txt"), "```",
        "## Session 2 - fuzzy engine checks\n", "```", _read(r / "s2_engine_checks.txt"), "```",
        "## Session 3 - Mamdani grid resolution (errors vs a 4001-point grid)\n", "```",
        _read(r / "s3_grid_resolution.csv"), "```",
        "## Session 4 - blocking analysis (concave cup U)\n", "```", _read(r / "s4_blocking.txt"), "```",
        _read(r / "s5_tables.md").replace("# Session 5", "## Session 5"),
        "\n### Does noise change the ranking?\n", "```", _read(r / "s5_noise_ranking.txt"), "```",
        _read(r / "s6_tables.md").replace("# Session 6", "## Session 6").replace("\n## ", "\n### "),
    ]
    (r / "RESULTS.md").write_text("\n".join(parts) + "\n", encoding="utf-8")
    print(f"  wrote {(r / 'RESULTS.md').relative_to(ctx.root)}")
